+package com.example;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/** Shared in-memory history, so it outlives individual ContactView instances. */
+@Service
+public class ContactMessageStore {
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public List<ContactMessage> newestFirst() {
+        return List.copyOf(messages);
+    }
+}
